<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/BusinessSelfOnboarding.php';
function check(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
$p=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$p->exec('PRAGMA foreign_keys=ON');
$p->exec(file_get_contents(dirname(__DIR__).'/database/sqlite.sql'));$p->exec(file_get_contents(dirname(__DIR__).'/database/destinations.sqlite.sql'));
$migrations=glob(dirname(__DIR__).'/database/migrations/*.sqlite.sql');sort($migrations);foreach($migrations as $file)if((int)basename($file)>=8)$p->exec(file_get_contents($file));
$p->exec('INSERT INTO destinations(id,slug,publication_status) VALUES(1,"ficticio","published");INSERT INTO destination_translations(destination_id,locale,display_name,headline,intro) VALUES(1,"es","Lugar ficticio","","");INSERT INTO service_categories(code,is_active) VALUES("hospedaje",1)');
foreach([1,2,3] as $id)$p->prepare('INSERT INTO accounts(id,public_id,account_type,display_name,email,status,email_verified_at) VALUES(?,?,"traveler",?,?,?,?)')->execute([$id,'account-'.$id,'Persona ficticia '.$id,'persona'.$id.'@example.invalid',$id===3?'pending_activation':'active',$id===3?null:'2026-10-20 00:00:00']);
function application(PDO $p,int $account,string $name,?int $business=null):int{
 $details=['onboarding_policy'=>BusinessSelfOnboarding::POLICY,'responsibility_declared'=>true,'categories'=>['hospedaje'],'location'=>['address_text'=>'','location_reference'=>'','latitude'=>null,'longitude'=>null,'location_source'=>null,'location_map_url'=>'','location_confirmed'=>0,'opening_hours'=>'','price_range'=>'','capacity_count'=>null,'menu_url'=>'','reservations_url'=>''],'text'=>[]];
 $p->prepare('INSERT INTO business_account_applications(account_id,application_type,business_id,destination_id,category_code,business_name,relationship_code,consent_version,business_details_json) VALUES(?,?,?,1,"hospedaje",?,"owner","test",?)')->execute([$account,$business?'claim_existing':'request_new',$business,$name,json_encode($details)]);$id=(int)$p->lastInsertId();
 $p->prepare('INSERT INTO business_account_application_evidence(application_id,evidence_type,storage_name,original_name,mime_type,file_size) VALUES(?,"business_registration","synthetic.pdf","Ficticio.pdf","application/pdf",100)')->execute([$id]);return $id;
}
function complete(PDO $p,int $id):void{$p->beginTransaction();try{BusinessSelfOnboarding::complete($p,$id);$p->commit();}catch(Throwable $e){$p->rollBack();throw $e;}}
$id=application($p,1,'Hotel Ficticio Uno');complete($p,$id);$business=(int)$p->query('SELECT business_id FROM business_account_applications WHERE id='.$id)->fetchColumn();
check($business>0,'create business');check($p->query('SELECT publication_status FROM businesses WHERE id='.$business)->fetchColumn()==='draft','publication remains separate');check($p->query('SELECT plan_code FROM business_subscriptions WHERE business_id='.$business)->fetchColumn()==='free','free exists automatically');
complete($p,$id);check((int)$p->query('SELECT COUNT(*) FROM business_subscriptions')->fetchColumn()===1,'retry does not duplicate subscription');check((int)$p->query('SELECT COUNT(*) FROM business_account_memberships')->fetchColumn()===1,'retry does not duplicate membership');
$dispute=application($p,2,'Hotel Ficticio Uno',$business);complete($p,$dispute);check($p->query('SELECT status FROM business_account_applications WHERE id='.$dispute)->fetchColumn()==='in_review','other account enters dispute');check((int)$p->query('SELECT account_id FROM business_account_memberships WHERE business_id='.$business.' AND status="active"')->fetchColumn()===1,'original responsible preserved');
$pending=application($p,3,'Hotel Ficticio Tres');complete($p,$pending);check(!$p->query('SELECT business_id FROM business_account_applications WHERE id='.$pending)->fetchColumn(),'unverified account gets no business');
$duplicate=application($p,2,'Hotel Ficticio Uno');complete($p,$duplicate);check($p->query('SELECT status FROM business_account_applications WHERE id='.$duplicate)->fetchColumn()==='needs_selection','duplicate leads to selection, no manual ordinary approval');check((int)$p->query('SELECT COUNT(*) FROM businesses')->fetchColumn()===1,'duplicate prevented');
$p->exec('INSERT INTO businesses(id,public_id,destination_id,category_code,slug) VALUES(5,"unclaimed",1,"hospedaje","otro");INSERT INTO business_translations(business_id,locale,display_name,summary,description) VALUES(5,"es","Otro Ficticio","","")');$claim=application($p,2,'Otro Ficticio',5);complete($p,$claim);check((int)$p->query('SELECT account_id FROM business_account_memberships WHERE business_id=5')->fetchColumn()===2,'existing unowned assigned same ID');
$again=application($p,2,'Otro Ficticio',5);complete($p,$again);check((int)$p->query('SELECT COUNT(*) FROM business_account_memberships WHERE business_id=5')->fetchColumn()===1,'same account not dispute');
$homonym=application($p,2,'Hotel Ficticio Uno');$h=json_decode($p->query('SELECT business_details_json FROM business_account_applications WHERE id='.$homonym)->fetchColumn(),true);$h['distinct_business_declared']=true;$h['location']['address_text']='Calle Ficticia 100';$p->prepare('UPDATE business_account_applications SET business_details_json=? WHERE id=?')->execute([json_encode($h),$homonym]);complete($p,$homonym);check($p->query('SELECT status FROM business_account_applications WHERE id='.$homonym)->fetchColumn()==='approved','declared distinct homonym with different address can participate');
$sameAddress=application($p,1,'Hotel Ficticio Uno');$p->prepare('UPDATE business_account_applications SET business_details_json=? WHERE id=?')->execute([json_encode($h),$sameAddress]);complete($p,$sameAddress);check($p->query('SELECT status FROM business_account_applications WHERE id='.$sameAddress)->fetchColumn()==='needs_selection','same-address override cannot create duplicate');
$p->prepare('UPDATE business_translations SET display_name="Nombre editado después" WHERE business_id=?')->execute([$business]);check($p->query('SELECT business_name FROM business_account_applications WHERE id='.$id)->fetchColumn()==='Hotel Ficticio Uno','editing business preserves submitted evidence');
$details=json_decode($p->query('SELECT business_details_json FROM business_account_applications WHERE id='.$id)->fetchColumn(),true);check($details['responsibility_association']['ownership_verified']===false,'not ownership certified');
echo "OK: declared-document onboarding, verified email, automatic Free, preserved IDs, idempotency, duplicate selection and real disputes\n";
// The same person can register in another municipality and keep the paid selection from the start.
$p->exec('INSERT INTO destinations(id,slug,department,publication_status) VALUES(9,"medellin","Antioquia","published");INSERT INTO destination_translations(destination_id,locale,display_name,headline,intro) VALUES(9,"es","Medellín","","")');
$secondPlace=application($p,1,'Casa Nébula');$data=json_decode($p->query('SELECT business_details_json FROM business_account_applications WHERE id='.$secondPlace)->fetchColumn(),true);$data['requested_subscription']=['plan_code'=>'page','billing_frequency'=>'quarterly'];$p->prepare('UPDATE business_account_applications SET destination_id=9,business_details_json=? WHERE id=?')->execute([json_encode($data),$secondPlace]);complete($p,$secondPlace);$secondBusiness=(int)$p->query('SELECT business_id FROM business_account_applications WHERE id='.$secondPlace)->fetchColumn();$selected=$p->query('SELECT plan_code,billing_frequency,status FROM business_subscriptions WHERE business_id='.$secondBusiness)->fetch();check($selected===['plan_code'=>'page','billing_frequency'=>'quarterly','status'=>'pending'],'paid subscription selected from first registration');check((int)$p->query('SELECT COUNT(DISTINCT b.destination_id) FROM businesses b JOIN business_account_memberships m ON m.business_id=b.id WHERE m.account_id=1 AND m.status="active"')->fetchColumn()===2,'one person across municipalities');complete($p,$secondPlace);check((int)$p->query('SELECT COUNT(*) FROM business_subscriptions WHERE business_id='.$secondBusiness)->fetchColumn()===1,'paid registration retry preserves selection');
echo "OK: multiple municipalities per person and paid selection without an intermediate Free plan\n";

$premiumApplication=application($p,1,'Premium de prueba');$details=json_decode($p->query('SELECT business_details_json FROM business_account_applications WHERE id='.$premiumApplication)->fetchColumn(),true);$details['requested_subscription']=['plan_code'=>'page_premium','billing_frequency'=>'annual'];$details['products']=[4=>['title'=>'Quinto producto','summary'=>'Descripción breve']];$details['source_images']=['product_4'=>str_repeat('a',40).'.png'];$p->prepare('UPDATE business_account_applications SET business_details_json=? WHERE id=?')->execute([json_encode($details),$premiumApplication]);$p->prepare('INSERT INTO business_application_images(application_id,storage_name,original_name,mime_type,file_size,width,height) VALUES(?,?,"quinto.png","image/png",100,640,480)')->execute([$premiumApplication,str_repeat('a',40).'.png']);complete($p,$premiumApplication);$business=(int)$p->query('SELECT business_id FROM business_account_applications WHERE id='.$premiumApplication)->fetchColumn();$saved=json_decode($p->query('SELECT payload_json FROM business_editorial_versions WHERE business_id='.$business)->fetchColumn(),true);check(($saved['showcase']['products'][4]['translations']['es']['name']??'')==='Quinto producto','onboarding lost fifth product');check(($saved['source_images']['product_4']??'')===str_repeat('a',40).'.png','onboarding lost image position');check((int)$p->query('SELECT COUNT(*) FROM business_editorial_images WHERE version_id=(SELECT MAX(id) FROM business_editorial_versions WHERE business_id='.$business.')')->fetchColumn()===1,'onboarding photo missing from private version');
echo "OK: initial Premium draft preserves sparse fifth product and its private image before payment\n";
